import java.util.*;

class Solution {
    public int sweepRoutes(int[][] grid) {
        int need = 0, si = 0, sj = 0;
        for (int i = 0; i < grid.length; i++)
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] != -1) need++;
                if (grid[i][j] == 1) { si = i; sj = j; }
            }
        return dfs(grid, si, sj, need);
    }

    private int dfs(int[][] g, int i, int j, int left) {
        if (g[i][j] == 2) return left == 1 ? 1 : 0;   // end counts only if all covered
        int v = g[i][j], total = 0;
        g[i][j] = -1;                                  // mark on current path
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            int a = i + d[0], b = j + d[1];
            if (a >= 0 && b >= 0 && a < g.length && b < g[0].length && g[a][b] != -1)
                total += dfs(g, a, b, left - 1);
        }
        g[i][j] = v;                                   // restore
        return total;
    }
}

