class Solution:
    def sweepRoutes(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        need = sum(v != -1 for row in grid for v in row)
        si, sj = next((i, j) for i in range(R) for j in range(C) if grid[i][j] == 1)
        def dfs(i, j, left):
            if grid[i][j] == 2: return 1 if left == 1 else 0
            v = grid[i][j]; grid[i][j] = -1; total = 0
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < R and 0 <= b < C and grid[a][b] != -1: total += dfs(a, b, left - 1)
            grid[i][j] = v
            return total
        return dfs(si, sj, need)

