function sweepRoutes(grid) {
  const R = grid.length, C = grid[0].length; let full = 0, start = 0, end = 0;
  for (let i = 0; i < R; i++) for (let j = 0; j < C; j++) {
    const id = i * C + j, v = grid[i][j];
    if (v !== -1) full |= 1 << id; if (v === 1) start = id; if (v === 2) end = id;
  }
  const memo = new Map();
  function f(cell, mask) {
    if (cell === end) return mask === full ? 1 : 0;
    const key = mask * 32 + cell; if (memo.has(key)) return memo.get(key);
    const i = Math.floor(cell / C), j = cell % C; let t = 0;
    for (const [a, b] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]]) {
      if (a < 0 || b < 0 || a >= R || b >= C) continue;
      const id = a * C + b;
      if ((full >> id & 1) && !(mask >> id & 1)) t += f(id, mask | (1 << id));
    }
    memo.set(key, t); return t;
  }
  return f(start, 1 << start);
}
